//! GRAND-297/298: empirical Z3-orbit transfer-matrix mass-gap report.
//!
//! Builds transfer surrogates from real lattice-time-series data generated by
//! Cl(1,3) / Z3 dynamics (`gutoe-em::sim::step_counted`), then extracts:
//! - λ0, λ1
//! - m_gap = -(1/a_t) ln(λ1/λ0)
//! - finite-volume trend and continuum a→0 extrapolation proxy.
//! - operator-basis GEVP hardening lane (correlator matrix approach).

use gutoe_em::{init_lattice, step_counted, LatticeConfig, VOID};
use gutoe_physics::mass_gap::{
    continuum_stability_band, monotone_nonincreasing_in_volume, transfer_matrix_diagnostics,
    DenseSymmetricMatrix, TransferMatrixGapEstimate, VolumeGapPoint,
};
use rand::rngs::StdRng;
use rand::SeedableRng;
use std::collections::HashSet;
use std::fs::{self, File};
use std::io::Write;

type Mat3 = [[f64; 3]; 3];

#[derive(Debug, Clone)]
struct SeedSeries {
    scalar: Vec<f64>,
    ops: Vec<[f64; 3]>,
}

#[derive(Debug, Clone)]
struct VolumeRow {
    side: usize,
    n_sites: usize,
    a2: f64,
    q1: f64,
    q2: f64,
    occupancy: [u64; 3],
    transitions: [[u64; 3]; 3],
    surrogate_gap: TransferMatrixGapEstimate,
    gevp_gap: Option<TransferMatrixGapEstimate>,
    seed_surrogate_mean: Option<f64>,
    seed_surrogate_std: Option<f64>,
    seed_gevp_mean: Option<f64>,
    seed_gevp_std: Option<f64>,
    gap: TransferMatrixGapEstimate,
    gap_source: &'static str,
    gap_err: f64,
}

fn env_usize(key: &str, default: usize) -> usize {
    std::env::var(key)
        .ok()
        .and_then(|v| v.parse::<usize>().ok())
        .unwrap_or(default)
}

fn env_f64(key: &str, default: f64) -> f64 {
    std::env::var(key)
        .ok()
        .and_then(|v| v.parse::<f64>().ok())
        .unwrap_or(default)
}

fn fmt_opt_json(v: Option<f64>) -> String {
    match v {
        Some(x) => format!("{x:.12e}"),
        None => "null".to_string(),
    }
}

fn z3_sector_signal(lattice: &[u8]) -> (f64, f64) {
    let mut bins = [0_u64; 3];
    let mut active = 0_u64;
    for &s in lattice {
        if s != VOID {
            bins[(s as usize) % 3] += 1;
            active += 1;
        }
    }
    let a = active.max(1) as f64;
    let skew01 = (bins[0] as f64 - bins[1] as f64) / a;
    let skew12 = (bins[1] as f64 - bins[2] as f64) / a;
    (skew01, skew12)
}

fn volume_config(side: usize) -> LatticeConfig {
    let mut cfg = LatticeConfig::default();
    cfg.hex_rows = side;
    cfg.hex_cols = side;
    cfg.layers = side;
    cfg
}

fn simulate_observables(
    cfg: &LatticeConfig,
    seed: u64,
    burn_in: usize,
    sample_steps: usize,
) -> SeedSeries {
    let mut rng = StdRng::seed_from_u64(seed);
    let mut lattice = init_lattice(cfg);
    let proton_sites: HashSet<usize> = HashSet::new();
    let mut scalar = Vec::with_capacity(sample_steps);
    let mut ops = Vec::with_capacity(sample_steps);

    for t in 0..(burn_in + sample_steps) {
        let (next, z3_cycles) = step_counted(&lattice, &mut rng, cfg, None, &proton_sites, t);
        lattice = next;
        if t >= burn_in {
            let active = lattice.iter().filter(|&&s| s != VOID).count().max(1) as f64;
            let cycle_density = z3_cycles as f64 / active;
            let (skew01, skew12) = z3_sector_signal(&lattice);
            let obs = cycle_density + 0.35 * skew01 + 0.20 * skew12;
            scalar.push(obs);
            ops.push([cycle_density, skew01, skew12]);
        }
    }

    SeedSeries { scalar, ops }
}

fn quantiles_terciles(values: &[f64]) -> (f64, f64) {
    let mut sorted = values.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let n = sorted.len();
    if n == 0 {
        return (0.0, 0.0);
    }
    let mut q1 = sorted[n / 3];
    let mut q2 = sorted[(2 * n) / 3];
    if (q2 - q1).abs() < 1e-12 {
        let mean = sorted.iter().sum::<f64>() / n as f64;
        let var = sorted
            .iter()
            .map(|x| {
                let d = *x - mean;
                d * d
            })
            .sum::<f64>()
            / n as f64;
        let sigma = var.sqrt().max(1e-6);
        q1 = mean - 0.25 * sigma;
        q2 = mean + 0.25 * sigma;
    }
    (q1, q2)
}

fn bin3(x: f64, q1: f64, q2: f64) -> usize {
    if x < q1 {
        0
    } else if x < q2 {
        1
    } else {
        2
    }
}

fn build_transfer_from_scalar_series(
    series_set: &[Vec<f64>],
) -> Option<(DenseSymmetricMatrix, [u64; 3], [[u64; 3]; 3], f64, f64)> {
    let all: Vec<f64> = series_set.iter().flat_map(|s| s.iter().copied()).collect();
    if all.len() < 8 {
        return None;
    }
    let (q1, q2) = quantiles_terciles(&all);

    let mut occ = [0_u64; 3];
    let mut trans = [[0_u64; 3]; 3];

    for s in series_set {
        if s.is_empty() {
            continue;
        }
        let states: Vec<usize> = s.iter().map(|&x| bin3(x, q1, q2)).collect();
        for &st in &states {
            occ[st] += 1;
        }
        for w in states.windows(2) {
            trans[w[0]][w[1]] += 1;
        }
    }

    let occ_total: f64 = occ.iter().sum::<u64>() as f64;
    if occ_total <= 0.0 {
        return None;
    }

    let alpha = 0.5_f64;
    let mut p = [[0.0_f64; 3]; 3];
    for i in 0..3 {
        let row_sum = trans[i].iter().sum::<u64>() as f64 + 3.0 * alpha;
        for j in 0..3 {
            p[i][j] = (trans[i][j] as f64 + alpha) / row_sum;
        }
    }

    let mut pi = [0.0_f64; 3];
    for i in 0..3 {
        pi[i] = (occ[i] as f64 + alpha) / (occ_total + 3.0 * alpha);
    }

    let mut s = [[0.0_f64; 3]; 3];
    for i in 0..3 {
        for j in 0..3 {
            if pi[i] > 0.0 && pi[j] > 0.0 {
                let a = (pi[i] / pi[j]).sqrt() * p[i][j];
                let b = (pi[j] / pi[i]).sqrt() * p[j][i];
                s[i][j] = 0.5 * (a + b);
            }
        }
    }

    for i in 0..3 {
        for j in 0..3 {
            let v = 0.5 * (s[i][j] + s[j][i]);
            s[i][j] = v.max(0.0);
        }
    }

    let mut t = [[0.0_f64; 3]; 3];
    for i in 0..3 {
        for j in 0..3 {
            for k in 0..3 {
                t[i][j] += s[i][k] * s[j][k];
            }
        }
    }

    let rows = vec![
        vec![t[0][0], t[0][1], t[0][2]],
        vec![t[1][0], t[1][1], t[1][2]],
        vec![t[2][0], t[2][1], t[2][2]],
    ];
    let tm = DenseSymmetricMatrix::from_rows(&rows)?;
    Some((tm, occ, trans, q1, q2))
}

fn mat3_t(a: Mat3) -> Mat3 {
    let mut out = [[0.0_f64; 3]; 3];
    for (i, row) in out.iter_mut().enumerate() {
        for (j, out_ij) in row.iter_mut().enumerate() {
            *out_ij = a[j][i];
        }
    }
    out
}

fn mat3_mul(a: Mat3, b: Mat3) -> Mat3 {
    let mut out = [[0.0_f64; 3]; 3];
    for (i, row) in out.iter_mut().enumerate() {
        for (j, out_ij) in row.iter_mut().enumerate() {
            let mut s = 0.0;
            for (k, b_row) in b.iter().enumerate() {
                s += a[i][k] * b_row[j];
            }
            *out_ij = s;
        }
    }
    out
}

fn mat3_sym(a: Mat3) -> Mat3 {
    let mut out = a;
    for i in 0..3 {
        for j in 0..3 {
            out[i][j] = 0.5 * (a[i][j] + a[j][i]);
        }
    }
    out
}

fn mat3_cholesky(a: Mat3) -> Option<Mat3> {
    let mut l = [[0.0_f64; 3]; 3];
    for i in 0..3 {
        for j in 0..=i {
            let mut sum = a[i][j];
            for k in 0..j {
                sum -= l[i][k] * l[j][k];
            }
            if i == j {
                if sum <= 1e-14 || !sum.is_finite() {
                    return None;
                }
                l[i][j] = sum.sqrt();
            } else {
                if l[j][j].abs() <= 1e-14 {
                    return None;
                }
                l[i][j] = sum / l[j][j];
            }
        }
    }
    Some(l)
}

fn mat3_inv_lower(l: Mat3) -> Option<Mat3> {
    let mut x = [[0.0_f64; 3]; 3];
    for col in 0..3 {
        for i in 0..3 {
            let mut rhs = if i == col { 1.0 } else { 0.0 };
            for (k, x_row) in x.iter().enumerate().take(i) {
                rhs -= l[i][k] * x_row[col];
            }
            if l[i][i].abs() <= 1e-14 {
                return None;
            }
            x[i][col] = rhs / l[i][i];
        }
    }
    Some(x)
}

fn correlation_matrix(series_set: &[Vec<[f64; 3]>], lag: usize) -> Option<Mat3> {
    let mut c = [[0.0_f64; 3]; 3];
    let mut n_pairs = 0usize;

    for s in series_set {
        if s.len() <= lag {
            continue;
        }

        let mut mean = [0.0_f64; 3];
        for x in s {
            for i in 0..3 {
                mean[i] += x[i];
            }
        }
        let inv_n = 1.0 / s.len() as f64;
        for m in &mut mean {
            *m *= inv_n;
        }

        for t in 0..(s.len() - lag) {
            let x = [
                s[t + lag][0] - mean[0],
                s[t + lag][1] - mean[1],
                s[t + lag][2] - mean[2],
            ];
            let y = [s[t][0] - mean[0], s[t][1] - mean[1], s[t][2] - mean[2]];
            for i in 0..3 {
                for (j, yj) in y.iter().enumerate() {
                    c[i][j] += x[i] * *yj;
                }
            }
            n_pairs += 1;
        }
    }

    if n_pairs == 0 {
        return None;
    }

    let inv = 1.0 / n_pairs as f64;
    for row in &mut c {
        for v in row {
            *v *= inv;
        }
    }
    Some(mat3_sym(c))
}

fn gevp_transfer_matrix(
    series_set: &[Vec<[f64; 3]>],
    t0: usize,
    t1: usize,
    reg_eps: f64,
) -> Option<DenseSymmetricMatrix> {
    if t1 <= t0 {
        return None;
    }
    let mut c0 = correlation_matrix(series_set, t0)?;
    let c1 = correlation_matrix(series_set, t1)?;

    for (i, row) in c0.iter_mut().enumerate() {
        row[i] += reg_eps;
    }

    let l = mat3_cholesky(c0)?;
    let linv = mat3_inv_lower(l)?;
    let linv_t = mat3_t(linv);

    // M = L^{-1} C(t1) L^{-T}, symmetric if C(t1) is symmetric and C(t0) SPD.
    let m = mat3_sym(mat3_mul(linv, mat3_mul(c1, linv_t)));

    let rows = vec![
        vec![m[0][0], m[0][1], m[0][2]],
        vec![m[1][0], m[1][1], m[1][2]],
        vec![m[2][0], m[2][1], m[2][2]],
    ];
    DenseSymmetricMatrix::from_rows(&rows)
}

fn linear_fit_intercept(points: &[(f64, f64)]) -> Option<(f64, f64)> {
    if points.len() < 2 {
        return None;
    }
    let n = points.len() as f64;
    let mean_x = points.iter().map(|p| p.0).sum::<f64>() / n;
    let mean_y = points.iter().map(|p| p.1).sum::<f64>() / n;
    let mut num = 0.0;
    let mut den = 0.0;
    for (x, y) in points {
        num += (x - mean_x) * (y - mean_y);
        den += (x - mean_x) * (x - mean_x);
    }
    if den <= 0.0 {
        return None;
    }
    let slope = num / den;
    let intercept = mean_y - slope * mean_x;
    Some((intercept, slope))
}

fn mean_std(values: &[f64]) -> Option<(f64, f64)> {
    if values.is_empty() {
        return None;
    }
    let n = values.len() as f64;
    let mean = values.iter().sum::<f64>() / n;
    let var = values
        .iter()
        .map(|v| {
            let d = *v - mean;
            d * d
        })
        .sum::<f64>()
        / n.max(1.0);
    Some((mean, var.sqrt()))
}

fn main() {
    let a_t = env_f64("GUTOE_YM_A_T", 1.0);
    let tol = env_f64("GUTOE_YM_TOL", 1e-10);
    let max_iters = env_usize("GUTOE_YM_MAX_ITERS", 20_000);
    let burn_in = env_usize("GUTOE_YM_BURN_IN", 24);
    let sample_steps = env_usize("GUTOE_YM_STEPS", 420);
    let seeds_per_volume = env_usize("GUTOE_YM_SEEDS", 6);
    let monotone_tol = env_f64("GUTOE_YM_MONO_TOL", 0.01);
    let t0 = env_usize("GUTOE_YM_GEVP_T0", 1);
    let t1 = env_usize("GUTOE_YM_GEVP_T1", 2);
    let reg_eps = env_f64("GUTOE_YM_GEVP_REG", 1e-8);
    let sides = [6usize, 8, 10, 12];

    let mut rows = Vec::<VolumeRow>::new();
    let mut points = Vec::<VolumeGapPoint>::new();
    let mut continuum_points = Vec::<(f64, f64)>::new();

    for &side in &sides {
        let cfg = volume_config(side);
        let mut seed_series = Vec::<SeedSeries>::with_capacity(seeds_per_volume);
        for k in 0..seeds_per_volume {
            let seed = 1729_u64 + (side as u64) * 10_000 + k as u64;
            seed_series.push(simulate_observables(&cfg, seed, burn_in, sample_steps));
        }

        let scalar_set: Vec<Vec<f64>> = seed_series.iter().map(|s| s.scalar.clone()).collect();
        let ops_set: Vec<Vec<[f64; 3]>> = seed_series.iter().map(|s| s.ops.clone()).collect();

        let mut seed_surrogate_gaps = Vec::<f64>::new();
        for s in &scalar_set {
            if let Some((tm_seed, _, _, _, _)) =
                build_transfer_from_scalar_series(std::slice::from_ref(s))
            {
                if let Some(diag_seed) = transfer_matrix_diagnostics(&tm_seed, a_t, max_iters, tol)
                {
                    if let Some(g_seed) = diag_seed.gap {
                        if g_seed.gap_est.is_finite() && g_seed.gap_est > 0.0 {
                            seed_surrogate_gaps.push(g_seed.gap_est);
                        }
                    }
                }
            }
        }
        let seed_surrogate_stats = mean_std(&seed_surrogate_gaps);

        let mut seed_gevp_gaps = Vec::<f64>::new();
        for s in &ops_set {
            if let Some(tm_seed) = gevp_transfer_matrix(std::slice::from_ref(s), t0, t1, reg_eps) {
                if let Some(diag_seed) =
                    transfer_matrix_diagnostics(&tm_seed, (t1 - t0) as f64 * a_t, max_iters, tol)
                {
                    if let Some(g_seed) = diag_seed.gap {
                        if g_seed.gap_est.is_finite() && g_seed.gap_est > 0.0 {
                            seed_gevp_gaps.push(g_seed.gap_est);
                        }
                    }
                }
            }
        }
        let seed_gevp_stats = mean_std(&seed_gevp_gaps);

        let Some((tm_surr, occ, trans, q1, q2)) = build_transfer_from_scalar_series(&scalar_set)
        else {
            continue;
        };
        let Some(diag_surr) = transfer_matrix_diagnostics(&tm_surr, a_t, max_iters, tol) else {
            continue;
        };
        let Some(surrogate_gap) = diag_surr.gap else {
            continue;
        };

        let gevp_gap = gevp_transfer_matrix(&ops_set, t0, t1, reg_eps)
            .and_then(|tm| transfer_matrix_diagnostics(&tm, (t1 - t0) as f64 * a_t, max_iters, tol))
            .and_then(|d| d.gap);

        let (gap, gap_source, seed_std) = if let Some(g) = gevp_gap.clone() {
            (g, "gevp", seed_gevp_stats.map(|(_, s)| s).unwrap_or(0.0))
        } else {
            (
                surrogate_gap.clone(),
                "surrogate",
                seed_surrogate_stats.map(|(_, s)| s).unwrap_or(0.0),
            )
        };

        let gap_lb = gap.gap_lower_bound.unwrap_or(gap.gap_est);
        let spectral_err = (gap.gap_est - gap_lb).abs();
        let gap_err = spectral_err.max(seed_std);

        let n_sites = cfg.n_sites();
        let a2 = 1.0 / ((side as f64) * (side as f64));

        rows.push(VolumeRow {
            side,
            n_sites,
            a2,
            q1,
            q2,
            occupancy: occ,
            transitions: trans,
            surrogate_gap,
            gevp_gap,
            seed_surrogate_mean: seed_surrogate_stats.map(|(m, _)| m),
            seed_surrogate_std: seed_surrogate_stats.map(|(_, s)| s),
            seed_gevp_mean: seed_gevp_stats.map(|(m, _)| m),
            seed_gevp_std: seed_gevp_stats.map(|(_, s)| s),
            gap: gap.clone(),
            gap_source,
            gap_err,
        });

        points.push(VolumeGapPoint {
            volume_l3: n_sites,
            gap_est: gap.gap_est,
            gap_err,
        });
        continuum_points.push((a2, gap.gap_est));
    }

    let monotone_ok = monotone_nonincreasing_in_volume(&points, monotone_tol);
    let band = continuum_stability_band(&points);
    let continuum_fit = linear_fit_intercept(&continuum_points);

    let out_dir = "/tmp/bh_renders";
    let _ = fs::create_dir_all(out_dir);
    let txt_path = format!("{out_dir}/ym_mass_gap_report.txt");
    let json_path = format!("{out_dir}/ym_mass_gap_report.json");

    let mut txt = File::create(&txt_path).expect("create txt");
    writeln!(txt, "GRAND-297/298 empirical Z3-orbit YM mass-gap report").expect("write");
    writeln!(
        txt,
        "a_t={:.6}, tol={:.2e}, burn_in={}, steps={}, seeds_per_volume={}, gevp=(t0={}, t1={}, reg={:.2e})",
        a_t, tol, burn_in, sample_steps, seeds_per_volume, t0, t1, reg_eps
    )
    .expect("write");
    writeln!(txt).expect("write");
    for r in &rows {
        writeln!(
            txt,
            "L={:>2} n_sites={:>4} a2={:.6} q1={:.6e} q2={:.6e} occ={:?} trans={:?}",
            r.side, r.n_sites, r.a2, r.q1, r.q2, r.occupancy, r.transitions
        )
        .expect("write");
        writeln!(
            txt,
            "  surrogate: λ0={:.9} λ1={:.9} gap={:.9}",
            r.surrogate_gap.lambda0_est, r.surrogate_gap.lambda1_est, r.surrogate_gap.gap_est
        )
        .expect("write");
        writeln!(
            txt,
            "  gevp:      λ0={:?} λ1={:?} gap={:?}",
            r.gevp_gap.as_ref().map(|g| g.lambda0_est),
            r.gevp_gap.as_ref().map(|g| g.lambda1_est),
            r.gevp_gap.as_ref().map(|g| g.gap_est)
        )
        .expect("write");
        writeln!(
            txt,
            "  chosen={} gap={:.9} gap_lb={:.9} seed_surrogate={:?}/{:?} seed_gevp={:?}/{:?} err={:.3e}",
            r.gap_source,
            r.gap.gap_est,
            r.gap.gap_lower_bound.unwrap_or(f64::NAN),
            r.seed_surrogate_mean,
            r.seed_surrogate_std,
            r.seed_gevp_mean,
            r.seed_gevp_std,
            r.gap_err
        )
        .expect("write");
    }

    writeln!(txt).expect("write");
    writeln!(
        txt,
        "monotone_nonincreasing_in_volume={} (tol={:.6})",
        monotone_ok, monotone_tol
    )
    .expect("write");
    writeln!(txt, "continuum_stability_band={:?}", band).expect("write");
    writeln!(
        txt,
        "continuum_fit_a2=(intercept,slope)={:?}",
        continuum_fit
    )
    .expect("write");
    if let Some((intercept, _)) = continuum_fit {
        writeln!(txt, "continuum_gap_positive={}", intercept > 0.0).expect("write");
    }

    let mut json = File::create(&json_path).expect("create json");
    writeln!(json, "{{").expect("write");
    writeln!(
        json,
        "  \"meta\": {{\"a_t\": {:.9}, \"tol\": {:.3e}, \"burn_in\": {}, \"steps\": {}, \"seeds_per_volume\": {}, \"gevp_t0\": {}, \"gevp_t1\": {}, \"gevp_reg\": {:.3e}}},",
        a_t, tol, burn_in, sample_steps, seeds_per_volume, t0, t1, reg_eps
    )
    .expect("write");
    writeln!(json, "  \"rows\": [").expect("write");

    for (idx, r) in rows.iter().enumerate() {
        writeln!(
            json,
            "    {{\"L\":{},\"n_sites\":{},\"a2\":{:.12e},\"q1\":{:.12e},\"q2\":{:.12e},\"occupancy\":[{},{},{}],\"transitions\":[[{},{},{}],[{},{},{}],[{},{},{}]],\"surrogate_lambda0\":{:.12e},\"surrogate_lambda1\":{:.12e},\"surrogate_gap_est\":{:.12e},\"gevp_lambda0\":{},\"gevp_lambda1\":{},\"gevp_gap_est\":{},\"seed_surrogate_mean\":{},\"seed_surrogate_std\":{},\"seed_gevp_mean\":{},\"seed_gevp_std\":{},\"gap_source\":\"{}\",\"gap_est\":{:.12e},\"gap_lower_bound\":{:.12e},\"gap_err\":{:.12e}}}{}",
            r.side,
            r.n_sites,
            r.a2,
            r.q1,
            r.q2,
            r.occupancy[0],
            r.occupancy[1],
            r.occupancy[2],
            r.transitions[0][0],
            r.transitions[0][1],
            r.transitions[0][2],
            r.transitions[1][0],
            r.transitions[1][1],
            r.transitions[1][2],
            r.transitions[2][0],
            r.transitions[2][1],
            r.transitions[2][2],
            r.surrogate_gap.lambda0_est,
            r.surrogate_gap.lambda1_est,
            r.surrogate_gap.gap_est,
            fmt_opt_json(r.gevp_gap.as_ref().map(|g| g.lambda0_est)),
            fmt_opt_json(r.gevp_gap.as_ref().map(|g| g.lambda1_est)),
            fmt_opt_json(r.gevp_gap.as_ref().map(|g| g.gap_est)),
            fmt_opt_json(r.seed_surrogate_mean),
            fmt_opt_json(r.seed_surrogate_std),
            fmt_opt_json(r.seed_gevp_mean),
            fmt_opt_json(r.seed_gevp_std),
            r.gap_source,
            r.gap.gap_est,
            r.gap.gap_lower_bound.unwrap_or(f64::NAN),
            r.gap_err,
            if idx + 1 == rows.len() { "" } else { "," }
        )
        .expect("write");
    }

    writeln!(json, "  ],").expect("write");
    writeln!(
        json,
        "  \"monotone_nonincreasing_in_volume\": {},",
        monotone_ok
    )
    .expect("write");

    match band {
        Some((lo, hi)) => {
            writeln!(
                json,
                "  \"continuum_stability_band\": {{\"lo\": {:.12e}, \"hi\": {:.12e}}},",
                lo, hi
            )
            .expect("write");
        }
        None => {
            writeln!(json, "  \"continuum_stability_band\": null,").expect("write");
        }
    }

    match continuum_fit {
        Some((intercept, slope)) => {
            writeln!(
                json,
                "  \"continuum_fit_a2\": {{\"intercept\": {:.12e}, \"slope\": {:.12e}, \"intercept_positive\": {}}}",
                intercept,
                slope,
                intercept > 0.0
            )
            .expect("write");
        }
        None => {
            writeln!(json, "  \"continuum_fit_a2\": null").expect("write");
        }
    }

    writeln!(json, "}}").expect("write");

    println!("wrote {txt_path}");
    println!("wrote {json_path}");
    println!(
        "YM empirical: rows={} monotone={} continuum_fit={:?} band={:?}",
        rows.len(),
        monotone_ok,
        continuum_fit,
        band
    );
}
